// План: .qa/e2e/specs/placement-results.md, тест 2.1 (тикет #c121d3). Запасной путь: генератор не нашёл seed.
// Только просмотр: профиль постоянного тестового ребёнка QA-R2-1 у родителя. Не прогонять при записи — запуск по /qa-regress.
// Сайт оборачивает числа в невидимые метки направления (U+2066…U+2069): «קריאה: ⁦5 / 10⁩» — поэтому проверки регулярками с BIDI.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/parent.json') });

const BIDI = '[\\u2066-\\u2069]?';
const CHILD = 'QA-R2-1';
const CHILD_ID = 'b9ef1552-4cc7-4d72-a9c3-d02d66d19af1';

test.describe('Уровни в зоне родителя — готовые профили (только просмотр)', () => {
  test('Профиль уверенно прошедшего ребёнка: «קריאה: 5 / 10» и «כתיבה: 2 / 4» @desktop #c121d3', async ({ page }) => {
    // 1. Список детей родителя
    await page.goto('/children');

    // 2. Профиль QA-R2-1 — через «עריכת פרופיל» (карточка сама ведёт на передачу устройства /handover)
    await page.getByRole('button', { name: `עריכת פרופיל ${CHILD}` }).click();
    await page.waitForURL(new RegExp(`/children/${CHILD_ID}$`));
    await expect(page.getByRole('textbox', { name: 'שם או כינוי' })).toHaveValue(CHILD);

    // AC3: блок уровней только для родителя
    await expect(page.getByText('רמות נוכחיות (להורה בלבד)')).toBeVisible();

    const reading = page.getByText(/קריאה:/);
    const writing = page.getByText(/כתיבה:/);
    // По одной строке на область
    await expect(reading).toHaveCount(1);
    await expect(writing).toHaveCount(1);

    // AC1, AC3: две области, разные шкалы (значения = skill_levels на 2026-10-29)
    await expect(reading).toHaveText(new RegExp(`^קריאה: ${BIDI}5 / 10${BIDI}$`));
    await expect(writing).toHaveText(new RegExp(`^כתיבה: ${BIDI}2 / 4${BIDI}$`));

    // Уверенное прохождение — без «עדיין לא ודאי»
    await expect(reading).not.toContainText('עדיין לא ודאי');
    await expect(writing).not.toContainText('עדיין לא ודאי');
  });
});
